entries[246727] = { ["name"] = "Astraler Essenzstreifen", ["text"] = "Unbezahlbar\nWird beim Aufheben gebunden\n\"Ein Stück des Verstands von Salhadaar, das vor Macht erstarrt ist.\"" }
entries[246730] = { ["name"] = "Landros Beutekiste", ["text"] = "Wird an Kriegsmeute gebunden\n\"WARNUNG: Ohne Gewähr. Enthält möglicherweise kein tatsächliches Reittier.\"" }
entries[246732] = { ["name"] = "Leerengeschmiedeter Aufseher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nachdem das Mausoleum der Ersten seine Pforten öffnete, wurde dieses Konstrukt der Ersten von den Mittlern gestohlen und bei einer Transaktion auf dem Verhüllten Markt an die Astralen verkauft. Mit den raffinierten Modifikationen der Astralen integriert es nun die Geheimnisse des Äthers und gleitet mit außergewöhnlicher Eleganz durch die Lüfte, wobei es eine schimmernde Spur aus Sternenstaub hinterlässt.\"\nAktion" }
entries[246737] = { ["name"] = "K'areshileerenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erfüllt Eure Rüstung mit einem schwachen Echo der Leere, was zusätzliche optische Effekte für bestimmte Klassensetvorlagen der Manaschmiede Omega, freischaltet.\n\nDieser Effekt gilt für die gesamte Kriegsmeute." }
