entries[246824] = { ["name"] = "Verzerrter Ernter der Schattenwache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, Chaosenergien aus dem Wirbelnden Nether zu ziehen, die Euch 10 Sek. lang 3371 Lebensraub gewähren. Wenn Eure Gesundheit unter 40% fällt, wird der Ernter sofort entfesselt und gewährt Euch 10 Sek. lang 10114 Lebensraub. Kann nur einmal alle 120 Sek. auftreten.\nVerkaufspreis:" }
entries[246825] = { ["name"] = "Chaotisches Nethertor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 1.256.\nBenutzen: Öffnet das Nethertor, um Eure Position mit verderbtem Mana zu überfluten, das allen darin befindlichen Gegnern 10 Sek. lang alle 1 Sek. 187998 Schaden zufügt und bis zu einem Maximum von 8 Zielen bis zu 27417 Gesundheit pro getroffenem Ziel heilt. (2 Min Abklingzeit)\nVerkaufspreis:" }
