entries[246904] = { ["name"] = "Unsichtbarer Pfad des Phasenpirschers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen reitbaren phasenverlorenen Sphärenjäger in K'aresh. Das ist ein sehr, SEHR schnelles Reittier. (2 Min Abklingzeit)\n\"Bereist die Sande von K'aresh, wie es die Ödnisbewohner lernten.\"" }
entries[246905] = { ["name"] = "Überjustierte K'areshibrille", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Sieht die Welt durch die Empfindsamkeiten der K'areshi. (30 Min Abklingzeit)\n\"Schönheit ist flüchtig. Immer.\"" }
