entries[246908] = { ["name"] = "Vorratskiste von K'aresh", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Tragt Eure Kiste voller Vorräte und Krimskrams der K'areshi. (10 Sek. Abklingzeit)" }
entries[246915] = { ["name"] = "Arsenal: Astrale Waffen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der astralen Waffen." }
entries[246917] = { ["name"] = "Donnergratelekk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Selbst durch die Infusion mit dämonischer Magie konnte der Wille dieser majestätischen Tiere nicht gebrochen werden, und ihre verderbten Formen wurden nie in den Dienst der Legion eingebunden.\"\nHandelsposten" }
entries[246919] = { ["name"] = "Glutversengter Elekk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Brennende Legion war darauf aus, alles zu zerstören, zu stehlen oder zu verderben, was den Draenei Freude bereitete. Und die Elekks von Draenor bildeten da keine Ausnahme.\"\nHandelsposten" }
entries[246920] = { ["name"] = "Leerengeschliffener Elekk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ihr Temperament ist so wild wie die verdrehten Kräfte, die ihre Schöpfung verzerrten. Sie dienen nur, wen sie dazu auserkoren haben.\"\nHandelsposten" }
entries[246921] = { ["name"] = "Legionsgeschmiedeter Elekk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Brennende Legion beneidete die Draenei um ihre Bande zu den Elekks von Draenor. Viele dämonische Bestienmeister verderbten die Spezies für ihre eigenen Bedürfnisse, doch kontrollieren konnte sie keiner.\"\nHandelsposten" }
entries[246936] = { ["name"] = "Resonantes Epochenandenken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fusioniert dieses Epochenandenken mit Eurer Artefaktwaffe, um eine Welle durch alle Zeitlinien und Versionen von \"Euch\" zu erzeugen.\n\nDieses mächtige Relikt steht in Resonanz mit Eurer Kriegsmeute und erhöht sämtliche erhaltene Erfahrung in Legion Remix dauerhaft um 1%.\n80 ( 80)\n\"Ein kleiner Teil einer epochalen Geschichte.\"" }
entries[246937] = { ["name"] = "Perfektioniertes Epochenandenken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fusioniert dieses Epochenandenken mit Eurer Artefaktwaffe, um eine Welle durch alle Zeitlinien und Versionen von \"Euch\" zu erzeugen.\n\nDieses perfekte Relikt steht in Resonanz mit Eurer Kriegsmeute und erhöht sämtliche erhaltene Erfahrung in Legion Remix dauerhaft um 10%.\n80 ( 80)\n\"Ein wichtiger Teil einer epochalen Geschichte.\"" }
entries[246939] = { ["name"] = "Augenglas des Essenzjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure kritischen Treffer mit schädlichen Zaubern und Distanzfähigkeiten haben eine hohe Chance, Euch bis zu 5-mal 'Arkanjäger' zu gewähren, was Euren kritischen Trefferwert 8 Sek. lang um 302 pro Stapel erhöht.\nVerkaufspreis:" }
entries[246940] = { ["name"] = "Manageschmiedete Ätherzelle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 Intelligenz\nAnlegen: Eure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 5250 , pro Sekunde um ( 5250 / 15) verringert. Hält 15 Sek. lang an.\nVerkaufspreis:" }
entries[246941] = { ["name"] = "Symbiotische Äthergaze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15.398 Ausdauer\nAnlegen: Blocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 232200 Arkanschaden zufügt und Euch einen Schild gewährt, der 1345046 Schaden absorbiert und 15 Sek. lang anhält.\nVerkaufspreis:" }
entries[246944] = { ["name"] = "Verstandvernichtendes Odium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke]\nAnlegen: Eure schädlichen Fähigkeiten können Risse in Eurem Verstand verursachen. Nach dem zehnten Riss erliegt Ihr dem arkanen Wahnsinn, was Euer Tempo um 2473 erhöht, während Ihr Euren Verstand allmählich mit der Zeit wiederherstellt.\n\nWenn Ihr einen Gegner tötet oder den Tod eines Verbündeten bezeugt, wird sofort ein Riss verursacht.\n\"Warum sind hier immer so viele Tentakel?\"\nVerkaufspreis:" }
entries[246945] = { ["name"] = "Körperloser Essenzverschlinger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Reißt magische Essenz aus Eurem Ziel und verschlingt sie, was dem Ziel ( 181008 * 1 ) Arkanschaden zufügt und Euch für 20 Sek. 5426 Eures niedrigsten Sekundärwerts gewährt.\n\nFalls das Ziel ein Astraler war, wird stattdessen Euer höchster Sekundärwert erhöht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[246947] = { ["name"] = "Verzerrter Managrimmling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 1.256 Vielseitigkeit\nAnlegen: Eure Heilzauber und -fähigkeiten haben eine sehr hohe Chance, einen verzerrten Managrimmling zu beschwören, der Euch 10 Sek. lang im Kampf unterstützt. Der verzerrte Managrimmling heilt regelmäßig einen zufälligen Verbündeten in der Nähe um ( 83617 * 1 ). Überschüssige Heilung wird in einen Absorptionsschild umgewandelt, der 5 Sek. lang anhält.\nVerkaufspreis:" }
