entries[247720] = { ["name"] = "Schauriges Streitross des kopflosen Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Fliegt durch die Lüfte, fahrt auf Eure Gegner herab, mit diesem Ross seid Ihr immer auf Zack.\"\nHandelsposten" }
entries[247721] = { ["name"] = "Makabres Streitross des kopflosen Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit süßem Sieg über einen garstigen Reiter, ein ghulisches Ross für einen schaurigen Streiter.\"\nBeute von:\nBeutegefüllter Kürbis\nFeiertag:\nSchlotternächte" }
entries[247722] = { ["name"] = "Brennendes Streitross des kopflosen Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In Herz und Seele des Rosses ein Feuer erhellt, steigt in den Himmel und zeigt es der Welt.\"\nHandelsposten" }
entries[247723] = { ["name"] = "Geheiligtes Streitross des kopflosen Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit ungewisser Zukunft dank vergangener Taten, wie lang könnt Ihr das mit Eurem Ross noch ertragen?\"\nHandelsposten" }
