entries[247791] = { ["name"] = "Geschmückter Greif von Nordaeron", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Greifenreiterältesten und Hochschamanen der Wildhämmer von Nordaeron haben ihre Greifen oft mit kunstvollen, federbedeckten Teilen geziert, die ihren Rang und Status zur Schau stellten.\"\nHandelsposten" }
entries[247792] = { ["name"] = "Fluggreif des Hochschamanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die antiken Schamanen der Wildhämmer, die den Greifen als erstes begegneten, glaubten, dass es sich bei ihnen um elementare Geister in sterblicher Form handelte. Diese Begegnung prägte den Wildhammerclan für alle kommenden Generationen.\"\nHandelsposten" }
entries[247793] = { ["name"] = "Glutgefiederter Hochlandgreif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Laut einer Legende der Wildhämmer soll das orangefarbene Gefieder der Greifen ein vererbtes Merkmal ihrer elementaren Vorfahren sein.\"\nHandelsposten" }
entries[247794] = { ["name"] = "Himmelsführer der Glutschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Von den Gebirgsausläufern Khaz Modans sind wir seinen flammenden Schwingen gefolgt... eine Fackel die am dunklen Sommerhimmel gen Norden flog.\" - Die Pilgerfahrt des Ersten Wildweisen\nHandelsposten" }
entries[247795] = { ["name"] = "Störrischer Brisenschreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nStörrischen Brisenschreiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Dieses Talbuk ist ein stures, eigensinniges Reittier, selbst wenn es mit seinem Reiter vertraut ist. Mit Vorsicht zu genießen.\"\nHandelsposten" }
entries[247808] = { ["name"] = "Bronzenes Simulakrum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Eine makellose Artefaktkopie, geschmiedet von Momentus. Jetzt, da Ihr diese Kopie in Händen haltet, könnt Ihr sie verschrottet, um die Bronze zu nutzen.\"" }
entries[247820] = { ["name"] = "Truhe mit Schätzen von K'aresh", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
