entries[247822] = { ["name"] = "Karmesinroter Leerenflieger", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von der Leere in den Wahnsinn getrieben, sind diese geflügelten Kreaturen ein Wirbel aus Klauen und Zähnen.\"\nErfolg:\nSchlüsselsteinlegende von The War Within: Saison 3\nKategorie:\nDungeons" }
