entries[247991] = { ["name"] = "Ensemble: Geheiligte Sammlung des Reiters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen dieses Rüstungssets.\n\"Wenn das Dunkel weicht und die Schatten fallen, strahlt Sir Thompson hell, in den heiligen Hallen.\"" }
entries[248009] = { ["name"] = "Fenster aus Suramar", ["text"] = "5\nFenster aus Suramar\nBehausungsdekoration\nWird an Kriegsmeute gebunden\nBenutzen: Fügt diese Dekoration zu Eurer Haustruhe hinzu.\nSchließt die Quest \"Thalyssras Schubladen\" ab.\nVerkaufspreis:" }
entries[248010] = { ["name"] = "Offenes Zelt der Shal'dorei", ["text"] = "5\nOffenes Zelt der Shal'dorei\nBehausungsdekoration\nWird bei Benutzung gebunden\nBenutzen: Fügt diese Dekoration zu Eurer Haustruhe hinzu.\nVerkaufspreis:" }
entries[248011] = { ["name"] = "Skelettdrachentrophäe der Volltrefferhütte", ["text"] = "5\nSkelettdrachentrophäe der Volltrefferhütte\nBehausungsdekoration\nWird an Kriegsmeute gebunden\nBenutzen: Fügt diese Dekoration zu Eurer Haustruhe hinzu.\nSchließt die Ordenshallenkampagne für Jäger ab." }
entries[248012] = { ["name"] = "Dorntannenholz", ["text"] = "Wird an Kriegsmeute gebunden\nHandwerksmaterial\n\"Holz, das in den Gegenden in und unter Khaz Algar geschlagen wurde.\"\nVerkaufspreis:" }
entries[248013] = { ["name"] = "Rezept: Dornische Stein- und Käseplatte", ["text"] = "Benutzen: Lehrt Euch, wie man eine dornische Stein- und Käseplatte herstellt. Dies ist ein dekorativer Gegenstand, der nicht gegessen werden kann.\nVerwendet Euer Kochwissen, um einen Modellteller herzustellen, der zwar Euren Bauch nicht voller macht, dafür aber Euer Haus.\nBenötigt Kochkunst von Khaz Algar (80)\nBenötigt Ruhmrang 22 beim Rat von Dornogal.\nVerkaufspreis:" }
entries[248017] = { ["name"] = "Kreischender Quarz", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt den kreischen Quarz auf und lockt die Nemesis an seine Position.\n\nKann nur verwendet werden, nachdem der Stein der Wiederherstellung in einer Tiefe aktiviert wurde. (1 Stunde Abklingzeit)\n\"Wurde nach dem unterschwelligen Geräusch benannt, den der Stein von sich gibt, wenn er im Freien rausgeholt wird. Seine Frequenzen unterbrechen den Manafluss, was für jene, die stärker auf Mana eingestimmt sind, überaus unangenehm ist.\"" }
entries[248088] = { ["name"] = "Jade, der strahlende Hellseher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Anwesenheit dieses erhabenen Pandaren-Hasengeists bringt Freude und Glück und gilt als wundervolles Omen. Der Legende nach könnt Ihr in den Augen dieser Geister das größte Glück Eures Lebens erblicken, selbst wenn es noch in der Zukunft liegt.\"\nWoW-Shop" }
entries[248089] = { ["name"] = "Umschlungener Traumweber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die letzten Schläfer erwachen endlich und bringen die Träume der Drachen zurück in die Welt.\"\nPromotion:\nDragonflight: Heroic Edition" }
entries[248090] = { ["name"] = "Viridianphasenjäger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Kreatur stammt von einer Spezies ab, die sich bereits zuvor äußerst geschickt auf natürliche Art und Weise tarnen konnte. Die außerweltlichen Energien, die Draenor in die Scherbenwelt verwandelten, gaben diesen Kreaturen die Fähigkeit, sich durch den Raum zu teleportieren.\"\nPromotion" }
entries[248091] = { ["name"] = "Animawyrmling", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nBeschwört diesen Gefährten oder gibt ihn wieder frei.\n80 ( 80)" }
entries[248092] = { ["name"] = "Zwinki", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[248093] = { ["name"] = "Ensemble: Schattenbannornat des Schreckenslords", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Schattenbannornats des Schreckenslords.\n\"Bei so einem Komfort ist es ganz einfach, grün zu leben.\"" }
entries[248094] = { ["name"] = "Ensemble: Ornat des wellengeborenen Diplomaten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Rüstungssets Ornat des wellengeborenen Diplomaten.\n\"Bei so einem Komfort ist es ganz einfach, grün zu leben.\"" }
