entries[248126] = { ["name"] = "Anfängerset des Tiefenforschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nQuest: Saisonale Erinnerung\n\"Enthält einen restaurierten Kastenschlüssel und einige verbrauchbare Gegenstände.\"\n<Zum Öffnen rechtsklicken>" }
entries[248127] = { ["name"] = "Tiefenforschertasche der kosmetischen Überraschung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nQuest: Saisonale Erinnerung\n\"Enthält einen zufälligen kosmetischen Gegenstand der Tiefe für Eure Kriegsmeute.\"\n<Zum Öffnen rechtsklicken>" }
entries[248129] = { ["name"] = "Branns wiedererlangte Ausrüstung", ["text"] = "Questgegenstand\n\"Jede Menge Kleidung, glücklicherweise, aber keinerlei Kuriosität.\"" }
entries[248140] = { ["name"] = "Bronzenes Simulakrum", ["text"] = "Wird beim Aufheben gebunden\n80 ( 80)\n\"Eine makellose Artefaktkopie, geschmiedet von Momentus. Jetzt, da Ihr diese Kopie in Händen haltet, könnt Ihr sie verschrottet, um die Bronze zu nutzen.\"" }
entries[248141] = { ["name"] = "Seltsames Simulakrum", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Untersucht das Simulaktrum und enthüllt seine wahre Natur.\n80 ( 80)\n\"Dies scheint just die Artefaktwaffe zu sein, die Ihr bereits in Händen haltet. Was ist das für ein Zauberwerk?\"" }
entries[248142] = { ["name"] = "Beute des Tiefenforschers", ["text"] = "The War Within – Saison 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Entschlüsselt zu einem beliebigen Zeitpunkt die Karte. So wird garantiert, dass Ihr am Ende der nächsten Tiefe der Stufe 4 oder höher, die Ihr abschließt, einen versteckten Schatz findet.\n\nDer Inhalt des versteckten Schatzes hängt von der Stufe der abgeschlossenen Tiefe ab.\n\"Bestimmt wartet dort ein großer Schatz.\"" }
entries[248199] = { ["name"] = "Endgültiges Geschenk der Brüder", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[248200] = { ["name"] = "Nicht ganz so endgültiges Geschenk der Brüder", ["text"] = "\"Kein richtiges Abschiedsgeschenk.\"\nVerkaufspreis:" }
