entries[248248] = { ["name"] = "Azurblauer Leerenflieger", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von der Leere verdorben, beherrschen diese geflügelten Kreaturen nun die Lüfte von K'aresh.\"\nErfolg:\nSchlüsselsteinmeister von The War Within: Saison 3\nKategorie:\nDungeons" }
